INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Dual-track — VeriFactu + Crea y Crece', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. The Crea y Crece implementing ministerial order remains unpublished as of this writing, meaning B2B format and exact dates could still change — confirm current requirements directly with the Agencia Tributaria before building an integration.', 'Three distinct regimes — B2G, SII, and now VeriFactu — have accumulated over a decade. Crea y Crece''s B2B mandate is the newest piece, and the one still missing its implementing detail.', 'The single most important thing to understand about Spain: VeriFactu is not an invoice format at all — it''s a requirement on the software that produces your invoices.', 'Spain runs two separate, complementary reforms that are easy to conflate: VeriFactu secures the invoicing software itself (confirmed dates, Jan/Jul 2027), while Crea y Crece mandates structured B2B invoice exchange (framework law passed, but the implementing ministerial order — and therefore the exact start dates — remains pending as of mid-2026). Beyond that distinction, Spain runs three parallel systems that don''t all talk to each other the same way — knowing which one applies to you matters as much as the technical detail.', 'Because two reforms are running on different tracks, your readiness checklist genuinely splits in two.', 'Spain''s penalty structure scales with the severity of the underlying issue — a formatting slip and outright fraud sit at opposite ends of a very wide range.' FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'RRSIF', 'VeriFactu technical standard');
