INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'VeriFactu (RRSIF) — a software requirement, not a format', '[["What it governs", "The invoicing system (SIF), not the invoice''s file format"], ["Core mechanisms", "Hash-chained records, digital signature, secure timestamp"], ["Visible marker", "QR code + legend \"VERI*FACTU\" or equivalent"]]', 'A VeriFactu-compliant invoice can still be a plain PDF in appearance — what matters is the underlying record''s integrity, not its visual format.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G format (already mandatory)', '[["Format", "Facturae 3.2.1 or 3.2.2"], ["Signature", "Qualified certificate required"], ["Delivery", "Via FACe (or FACeB2B for procurement chains)"]]', 'This has applied for over a decade and isn''t changing — treat it as the stable baseline while VeriFactu and Crea y Crece both continue to develop.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B format (Crea y Crece, pending)', '[["Expected formats", "Facturae and/or UBL-compatible standards"], ["Confirmed requirement", "EN 16931 content validation"], ["Status", "Final format not locked until the ministerial order publishes"]]', 'Don''t build a specific B2B schema assumption into production systems yet — Facturae and UBL are both plausible, and the order will settle it.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Software declaration (SIF)', '[["Requirement", "Declaraci\u00f3n responsable filed with AEAT"], ["Filed by", "The software developer, not the end-user business"], ["Must be visible", "In the system itself, per version, from time of purchase"]]', 'If you''re a business rather than a software vendor, your job is confirming your provider has filed this declaration — not filing it yourself.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'SII vs. VeriFactu', '[["SII scope", "Large taxpayers, monthly filers"], ["SII cadence", "Ledger reporting within 4 days"], ["VeriFactu scope", "Everyone else using invoicing software"]]', 'These are mutually exclusive — if you''re in SII, you are explicitly out of VeriFactu''s scope. Don''t build for both.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'VeriFactu''s two modes', '[["Mode A", "Real-time transmission to AEAT"], ["Mode B", "Local storage under strict hash-chain/audit requirements"]]', 'Both modes satisfy the legal requirement — the choice is about your operational preference for live reporting versus retained, tamper-evident local records.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Crea y Crece network (pending detail)', '[["Public option", "State platform, receiving a \"copia fiel\" (faithful copy)"], ["Private option", "Connected private operators"], ["Status", "Full network model still to be finalised by the ministerial order"]]', 'The B2B e-invoice network does not send invoice content to AEAT the way VeriFactu can — it''s a separate exchange-and-status-tracking layer between trading partners.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'AEAT''s audit powers', '[["Access", "Full, immediate access to SIF data on request"], ["On-site powers", "Can appear where the system is located/used"], ["Actions available", "Download, dump, consult, or copy data directly"]]', 'This is a materially stronger inspection power than most EU e-invoicing regimes grant — plan your system architecture assuming AEAT can and will exercise it.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ Software providers carry real exposure', NULL, NULL, 'The €150,000/year penalty for non-compliant software applies to the vendor, not just the end user — a strong incentive for Spanish SIF developers to get RRSIF certification genuinely right rather than cut corners.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔀 Two reforms, two enforcement pictures', NULL, NULL, 'VeriFactu''s penalties are confirmed and tied to firm 2027 dates; Crea y Crece''s enforcement detail will only become clear once its ministerial order publishes — don''t assume the same fine structure applies to both.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Beyond fines', NULL, NULL, 'AEAT''s power to demand immediate, full access to your SIF system means non-compliance risk extends well past financial penalties into direct operational disruption during an inspection.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Determine your regime: SII or VeriFactu', 'Check whether you''re a large taxpayer or monthly filer already in SII — if so, VeriFactu doesn''t apply to you at all.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your software vendor''s AEAT declaration', 'Ask your invoicing software provider to confirm they''ve filed the declaración responsable for your specific version — this is their obligation, not yours, but you need the assurance.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your VeriFactu mode ahead of your deadline', 'Corporate taxpayers: decide real-time AEAT transmission vs. local hash-chained storage before 1 January 2027. Autónomos and others: the same decision applies before 1 July 2027.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Keep your B2G channel current', 'If you already invoice public bodies, confirm Facturae 3.2.1/3.2.2 generation and FACe submission remain in good working order — this obligation isn''t changing.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for the Crea y Crece ministerial order', 'Once published, your compliance clock starts immediately — 1 year if you''re above €8 million turnover, 2 years otherwise. Don''t wait until publication to start evaluating platforms.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Spain';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up dual-track archiving', 'Plan for 4-year tax retention and 6-year commercial retention separately, and notify AEAT if any records are hosted abroad.');
